**The contract under test** (already deployed in this course's examples):

```solidity
// src/Vault.sol
contract Vault {
    error InsufficientBalance();
    error ZeroAmount();

    address public owner;
    mapping(address => uint256) public balances;

    constructor(address _owner) {
        owner = _owner;
    }

    function deposit() external payable {
        if (msg.value == 0) revert ZeroAmount();
        balances[msg.sender] += msg.value;
    }

    function withdraw(uint256 amount) external {
        if (balances[msg.sender] < amount) revert InsufficientBalance();
        balances[msg.sender] -= amount;
        payable(msg.sender).transfer(amount);
    }

    function emergencyWithdraw() external {
        require(msg.sender == owner, "Ownable: caller is not the owner");
        payable(owner).transfer(address(this).balance);
    }
}
```

**What's already known from Chapter 1:** `vm.expectRevert`/`vm.prank` assert failure paths (Lesson 1); fuzz tests let Forge supply inputs, constrained with `bound()` (Lesson 2); invariant tests throw sequences of calls at the whole contract via a handler (Lesson 3); and a high coverage percentage only proves code ran, not that it was checked correctly (Lesson 6).

