```solidity
// test/Vault.t.sol
import {Test} from "forge-std/Test.sol";
import {Vault} from "../src/Vault.sol";

contract VaultTest is Test {
    Vault vault;
    address owner = address(0x1);
    address attacker = address(0x2);

    function setUp() public {
        vault = new Vault(owner);
    }

    // --- Lesson 1: happy path + failure categories ---
    function test_DepositAndWithdraw() public {
        vault.deposit{value: 1 ether}();
        vault.withdraw(1 ether);
        assertEq(address(vault).balance, 0);
    }

    function test_RevertWhen_WithdrawExceedsBalance() public {
        vault.deposit{value: 1 ether}();
        vm.expectRevert(Vault.InsufficientBalance.selector);
        vault.withdraw(2 ether);
    }

    function test_RevertWhen_ZeroDeposit() public {
        vm.expectRevert(Vault.ZeroAmount.selector);
        vault.deposit{value: 0}();
    }

    function test_RevertWhen_UnauthorizedEmergencyWithdraw() public {
        vm.prank(attacker);
        vm.expectRevert("Ownable: caller is not the owner");
        vault.emergencyWithdraw();
    }

    // --- Lesson 2: fuzz the boundary instead of hand-picking it ---
    function testFuzz_WithdrawNeverExceedsBalance(uint256 depositAmount, uint256 withdrawAmount) public {
        depositAmount = bound(depositAmount, 1, 1_000_000 ether);
        vm.deal(address(this), depositAmount);
        vault.deposit{value: depositAmount}();

        if (withdrawAmount > depositAmount) {
            vm.expectRevert(Vault.InsufficientBalance.selector);
            vault.withdraw(withdrawAmount);
        } else {
            vault.withdraw(withdrawAmount);
            assertEq(vault.balances(address(this)), depositAmount - withdrawAmount);
        }
    }

    // --- Lesson 1 + 2: fuzz the caller, not just the amount ---
    function testFuzz_OnlyOwnerCanEmergencyWithdraw(address caller) public {
        vm.assume(caller != owner);
        vm.prank(caller);
        vm.expectRevert("Ownable: caller is not the owner");
        vault.emergencyWithdraw();
    }
}
```

```solidity
// test/handlers/VaultHandler.sol — Lesson 3
contract VaultHandler is Test {
    Vault public vault;
    address[] public actors;
    mapping(address => uint256) public deposited;

    constructor(Vault _vault) {
        vault = _vault;
        for (uint256 i = 0; i < 5; i++) {
            actors.push(address(uint160(0x1000 + i)));
        }
    }

    function deposit(uint256 actorSeed, uint256 amount) public {
        address actor = actors[actorSeed % actors.length];
        amount = bound(amount, 1, 100 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        vault.deposit{value: amount}();
        deposited[actor] += amount;
    }

    function withdraw(uint256 actorSeed, uint256 amount) public {
        address actor = actors[actorSeed % actors.length];
        uint256 bal = vault.balances(actor);
        if (bal == 0) return;
        amount = bound(amount, 0, bal);
        vm.prank(actor);
        vault.withdraw(amount);
        deposited[actor] -= amount;
    }
}
```

```solidity
// test/Vault.invariant.t.sol — Lesson 3
contract VaultInvariantTest is Test {
    Vault vault;
    VaultHandler handler;

    function setUp() public {
        vault = new Vault(address(0x1));
        handler = new VaultHandler(vault);
        targetContract(address(handler));
    }

    function invariant_BalanceMatchesSumOfDeposits() public {
        assertEq(address(vault).balance, handler.deposited(address(0x1000)) +
            handler.deposited(address(0x1001)) + handler.deposited(address(0x1002)) +
            handler.deposited(address(0x1003)) + handler.deposited(address(0x1004)));
    }
}
```

