// script/Deploy.s.sol
import {Script} from "forge-std/Script.sol";
import {Vault} from "../src/Vault.sol";

contract DeployScript is Script {
    function run() external {
        address owner = vm.envAddress("VAULT_OWNER"); // the Safe's address on mainnet
        address feeRecipient = vm.envAddress("FEE_RECIPIENT");
        uint256 feeBps = 50; // 0.5%

        vm.startBroadcast();
        Vault vault = new Vault(owner, feeRecipient, feeBps);
        vm.stopBroadcast();

        console.log("Vault deployed at:", address(vault));
    }
}
```

```bash
# Step 2 — dry run, no transaction sent
forge script script/Deploy.s.sol --rpc-url sepolia

# Step 3 — real testnet deploy, keystore account
VAULT_OWNER=0xTestOwner FEE_RECIPIENT=0xTestFeeRecipient \
  forge script script/Deploy.s.sol --broadcast --rpc-url sepolia --account deployer

# Step 4 — verify on Sepolia
forge verify-contract <deployed_address> src/Vault.sol:Vault \
  --chain sepolia --etherscan-api-key $ETHERSCAN_API_KEY

# Step 5 — mainnet deploy, owner = Safe multisig address
VAULT_OWNER=0xYourSafeMultisigAddress FEE_RECIPIENT=0xRealFeeRecipient \
  forge script script/Deploy.s.sol --broadcast --rpc-url mainnet --account deployer \
  --verify --etherscan-api-key $ETHERSCAN_API_KEY
```

